
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.303465373948382e+00, -4.221751049624943e+00, -4.107359609060284e+00, -3.949129822569399e+00, -3.734006699659131e+00, -3.448712850422249e+00, -3.083625834609069e+00, -2.639600591345347e+00, -2.136180985211459e+00, -1.610340416084144e+00, -1.087329730878614e+00, -7.092149946005094e-01, -6.021127611513660e-01, -5.013191985426525e-01, -3.704450871775299e-01, -2.428195080665577e-01, -1.333542958376418e-01, -4.952125143258846e-02, -1.081192727292373e-02, -1.216202148796273e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


